"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[36239],{3331:(e,n,i)=>{i.d(n,{R:()=>o,x:()=>s});var r=i(36672);const t={},a=r.createContext(t);function o(e){const n=r.useContext(a);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),r.createElement(a.Provider,{value:n},e.children)}},54248:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>v,frontMatter:()=>o,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/04/08","title":"2023-04-08","description":"GitHub bouwen met Ruby on Rails","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/08.md","sourceDirName":"2023/04","slug":"/2023/04/08","permalink":"/nl/2023/04/08","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/08.md","tags":[],"version":"current","frontMatter":{"localized_date":"8 april 2023","top_news":"GitHub bouwen met Ruby on Rails"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-09","permalink":"/nl/2023/04/09"},"next":{"title":"2023-04-07","permalink":"/nl/2023/04/07"}}');var t=i(23420),a=i(3331);const o={localized_date:"8 april 2023",top_news:"GitHub bouwen met Ruby on Rails"},s="2023-04-08",d={},l=[{value:"GitHub bouwen met Ruby on Rails",id:"github-bouwen-met-ruby-on-rails",level:2},{value:"Vraag het Wirecutter: Kunt u mij een niet-slimme tv aanbevelen?",id:"vraag-het-wirecutter-kunt-u-mij-een-niet-slimme-tv-aanbevelen",level:2},{value:"Codeberg - Snel open source alternatief voor GitHub",id:"codeberg---snel-open-source-alternatief-voor-github",level:2},{value:"Meerjarige rijst: Eenmaal planten, steeds opnieuw oogsten",id:"meerjarige-rijst-eenmaal-planten-steeds-opnieuw-oogsten",level:2},{value:"Voor 60 miljoen Amerikanen zijn de belastingen zo eenvoudig dat de belastingdienst ze automatisch kan doen.",id:"voor-60-miljoen-amerikanen-zijn-de-belastingen-zo-eenvoudig-dat-de-belastingdienst-ze-automatisch-kan-doen",level:2},{value:"We moeten de mensen vertellen dat ChatGPT tegen hen zal liegen, niet debatteren over taalkunde",id:"we-moeten-de-mensen-vertellen-dat-chatgpt-tegen-hen-zal-liegen-niet-debatteren-over-taalkunde",level:2},{value:"Twitter staat het retweeten van tweets met een link naar Substack niet toe.",id:"twitter-staat-het-retweeten-van-tweets-met-een-link-naar-substack-niet-toe",level:2},{value:"Western Digital clouddiensten 4 dagen uit de lucht.",id:"western-digital-clouddiensten-4-dagen-uit-de-lucht",level:2},{value:"Hoe werkt database sharding?",id:"hoe-werkt-database-sharding",level:2},{value:"Hubble ziet mogelijk op hol geslagen zwart gat dat een spoor van sterren cre\xebert",id:"hubble-ziet-mogelijk-op-hol-geslagen-zwart-gat-dat-een-spoor-van-sterren-cre\xebert",level:2},{value:"NZ&#39;s grootste datalek laat zien dat retentie de slapende reus van gegevensbeveiliging is",id:"nzs-grootste-datalek-laat-zien-dat-retentie-de-slapende-reus-van-gegevensbeveiliging-is",level:2},{value:"VS en China voeren oorlog onder de golven over internetkabels",id:"vs-en-china-voeren-oorlog-onder-de-golven-over-internetkabels",level:2},{value:"Database &quot;sharding&quot; kwam van Ultima Online?",id:"database-sharding-kwam-van-ultima-online",level:2},{value:"Waarom deelde Phreesia mijn medische gegevens nadat ik me had afgemeld?",id:"waarom-deelde-phreesia-mijn-medische-gegevens-nadat-ik-me-had-afgemeld",level:2},{value:"JavaScript-algoritmen: Algoritmen en gegevensstructuren ge\xefmplementeerd in JavaScript",id:"javascript-algoritmen-algoritmen-en-gegevensstructuren-ge\xefmplementeerd-in-javascript",level:2},{value:"SpaceX nadert eerste Starship Super Heavy lancering",id:"spacex-nadert-eerste-starship-super-heavy-lancering",level:2},{value:"muzikale synthesizers bouwen met SQL queries.",id:"muzikale-synthesizers-bouwen-met-sql-queries",level:2},{value:"De langste rechte lijn in Groot-Brittanni\xeb zonder een openbare weg te kruisen",id:"de-langste-rechte-lijn-in-groot-brittanni\xeb-zonder-een-openbare-weg-te-kruisen",level:2},{value:"Flipper Zero verboden door Amazon omdat het een &quot;card skimming device&quot; is",id:"flipper-zero-verboden-door-amazon-omdat-het-een-card-skimming-device-is",level:2},{value:"Omgekeerde engineering van de Facebook Messenger API",id:"omgekeerde-engineering-van-de-facebook-messenger-api",level:2},{value:"De machines van Tatjana van Vark",id:"de-machines-van-tatjana-van-vark",level:2},{value:"Grote bal modder (1999)",id:"grote-bal-modder-1999",level:2},{value:"Yann LeCun en Andrew Ng: Waarom de AI-pauze van 6 maanden een slecht idee is [video].",id:"yann-lecun-en-andrew-ng-waarom-de-ai-pauze-van-6-maanden-een-slecht-idee-is-video",level:2},{value:"NSA cre\xeberde online cursus cyberbeveiliging met 100 lessen",id:"nsa-cre\xeberde-online-cursus-cyberbeveiliging-met-100-lessen",level:2},{value:"Slechte systemen vervangen door slechte systemen",id:"slechte-systemen-vervangen-door-slechte-systemen",level:2},{value:"Neovim 0.9",id:"neovim-09",level:2},{value:"Vraag Wat is uw beste bron om op de hoogte te blijven van AI-ontwikkelingen?",id:"vraag-wat-is-uw-beste-bron-om-op-de-hoogte-te-blijven-van-ai-ontwikkelingen",level:2},{value:"Direct bewijs van het gebruik van meerdere drugs in de Bronstijd uit een menselijke haartest.",id:"direct-bewijs-van-het-gebruik-van-meerdere-drugs-in-de-bronstijd-uit-een-menselijke-haartest",level:2},{value:"NYPD agenten scheppen op over het uitmelken van overuren in toevallige opname.",id:"nypd-agenten-scheppen-op-over-het-uitmelken-van-overuren-in-toevallige-opname",level:2},{value:"Toon ChatGDB - GPT-aangedreven GDB-assistent",id:"toon-chatgdb---gpt-aangedreven-gdb-assistent",level:2}];function g(e){const n={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-08",children:"2023-04-08"})}),"\n",(0,t.jsx)(n.h2,{id:"github-bouwen-met-ruby-on-rails",children:"GitHub bouwen met Ruby on Rails"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.blog/2023-04-06-building-github-with-ruby-and-rails/",children:"Origineel"}),".\nGitHub.com is geschreven met Ruby on Rails en wordt onderhouden door meer dan duizend ingenieurs met bijna 2 miljoen regels code. Het bedrijf upgradet wekelijks naar de nieuwste Rails commit met pull requests en revision reviews. Voordelen van deze upgrades zijn een betere afhandeling van databaseverbindingen en snellere weergave van weergaven, verbeterde beveiliging en een lager risico op onbekende problemen. Het testen van de nieuwste versies identificeert en verhelpt problemen v\xf3\xf3r de release. Het bericht is een GitHub Privacy Statement, met informatie over productfuncties, beveiliging, verhalen, prijzen, bronnen, ontwikkelaars-API, partners, platform en ondersteuning. De post lijkt geen nieuwe informatie of gebeurtenissen te bevatten, en het is onduidelijk waarom het de aandacht trekt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35478884",children:"Discussion Service"}),".\nGitHub herbouwt zijn platform met Ruby on Rails, wat de interesse wekt voor de potenti\xeble impact op het Rails-ecosysteem & de vereisten voor testdekking. Gebruikers benadrukken de uitdagingen van het beheersen van Ruby, zoals extreme testdekking & potentieel voor toekomstige codefouten. Sommige gebruikers stellen voor Sorbet te gebruiken voor sterkere controletypes. GitHub's gebruik van Crystal language en Ruby's metaprogrammeer potentieel wordt geprezen, terwijl sommigen kritiek hebben op Ruby's data science ruimte. De recente upgrade van Github's Rails platform van versie 2.3 naar 3 leverde uitdagingen op, maar statische typering helpt bij upgrades. Ontwikkelaars denken na over de afweging tussen technische trends en gevestigde stabiliteit, waarbij sommigen het gebruiksgemak van Rails maar de achterblijvende view-laag opmerken. Framework-upgrades worden het best geleidelijk uitgevoerd, met goede tests. Veel organisaties vinden het bijwerken van de IT-infrastructuur belangrijk, de testmogelijkheden van GitHub worden geprezen, en Sorbet wordt door GitHub gebruikt voor Ruby en Rails."]}),"\n",(0,t.jsx)(n.h2,{id:"vraag-het-wirecutter-kunt-u-mij-een-niet-slimme-tv-aanbevelen",children:"Vraag het Wirecutter: Kunt u mij een niet-slimme tv aanbevelen?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/",children:"Origineel"}),".\nWirecutter stelt voor om slimme tv's te beveiligen in plaats van niet-slimme opties te vinden vanwege zorgen over de privacy. Niet-slimme tv's kunnen nuttige functies missen. Experts adviseren om af te zien van gegevensverzameling, alleen verbinding te maken met Wi-Fi voor firmware-updates en af en toe te streamen om zich af te melden. Oude tv's, 4K-monitoren of projectoren zijn alternatieven. Soortgelijke privacyproblemen blijven bestaan met andere op internet aangesloten apparaten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35484594",children:"Discussion Service"}),".\nEen artikel bespreekt de moeilijkheid om een niet-intelligente tv te vinden zonder opdringerige en onnodige functies. Voorgestelde oplossingen zijn onder meer het gebruik van een niet-slimme tv of het fysiek loskoppelen van modules om ongewenste verbindingen te voorkomen. Er is bezorgdheid over privacy en exfiltratie van gegevens. Discussie over energieverbruik, mogelijke automatische verbindingen en het langzame opstartproces van smart tv's door gebruikers. Suggesties voor een mogelijke naam voor een niet-slimme tv en ideale functies voor slimme tv's. Zorgen over het bijhouden van gegevens en de moeilijkheid om een hoogwaardige, domme display op te starten. Gebruikers bespreken specifieke displayfuncties en de moeilijkheid om smart TV's niet aan te sluiten. Het onethische gedrag van TCL en de zorgen van gebruikers over hun privacy worden belicht."]}),"\n",(0,t.jsx)(n.h2,{id:"codeberg---snel-open-source-alternatief-voor-github",children:"Codeberg - Snel open source alternatief voor GitHub"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://codeberg.org/",children:"Origineel"}),".\nCodeberg.org is een vrij en open-source software samenwerkingsplatform en Git hosting gerund door zijn gebruikers via een non-profit organisatie in Berlijn. Het platform bevordert ook een gemeenschap van gelijkgestemde makers van vrije software en inhoud zonder tracking of verkoop van gebruikersgegevens. Gebruikers kunnen zich registreren en hun projecten hosten op de website, en Codeberg e.V. onderhoudt de gemeenschap door middel van donaties en optionele bijdragen. De website is toegankelijk in meerdere talen, en gebruikers kunnen bijdragen aanbieden om de diensten achter Codeberg te verbeteren."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35480056",children:"Discussion Service"}),".\nCodeberg biedt een snel, open-source alternatief voor Github dat zich richt op vrije en open-source software samenwerking. Discussion Service gebruikers discussi\xebren of Codeberg's focus op open source ethiek te beperkend is, terwijl anderen het juist prijzen om zijn betrokkenheid. Over de politieke aard van de IT-infrastructuur stellen sommigen dat neutraliteit onmogelijk is maar toch nagestreefd moet worden, terwijl anderen beweren dat politieke meningen in de IT meer getolereerd worden dan in andere contexten. Discussion Service-gebruikers bespreken ook de filosofie van het delen van code, restrictieve licenties en de invloed van bedrijfsvriendelijke codes op de succespercentages van FOSS. Codeberg's non-profit status en toewijding aan vrije software licenties worden geprezen. De snelle snelheid van het platform en de eenvoudige interface worden gewaardeerd, maar er zijn zorgen over de privacy. Sommigen bevelen Radicle aan als alternatief voor gecentraliseerde diensten zoals Github."]}),"\n",(0,t.jsx)(n.h2,{id:"meerjarige-rijst-eenmaal-planten-steeds-opnieuw-oogsten",children:"Meerjarige rijst: Eenmaal planten, steeds opnieuw oogsten"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again",children:"Origineel"}),".\nWetenschappers hebben meerjarige rijststammen gecre\xeberd die productief blijven en na elke oogst opnieuw groeien, wat leidt tot enorme milieuvoordelen, een kleinere koolstofvoetafdruk, gezondere grond en boeren die niet opnieuw hoeven te zaaien. Deze rassen, die de afgelopen twee decennia zijn gekweekt, zijn vier jaar achtereen getest en geoogst door 45.000 kleine boeren die voor eigen gebruik produceren. Deskundigen voorspellen dat als meer boeren de nieuwe rassen gaan gebruiken, de voordelen groot kunnen zijn voor de mensen die ze verbouwen, het milieu en de wereldbevolking die afhankelijk is van rijst als basisvoedsel."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481409",children:"Discussion Service"}),".\nMeerjarige rijst kan de methaanuitstoot van rijstvelden verminderen. Veeteelt heeft een aanzienlijke invloed op het milieu. Klimaatverandering zal leiden tot voedseltekorten en andere problemen. Methaan uit rijstvelden heeft geen significant effect in vergelijking met andere bronnen. Meerjarige rijst heeft potenti\xeble voordelen maar ook uitdagingen. Deskundigen bespreken landbouw en voedselproductie. Het succes van ge\xefrrigeerde meerjarige rijst wordt geschetst. Meerjarige gewassen kunnen besparen op arbeids- en inputkosten. Meerjarige gewassen hebben voordelen voor de bodem en het onttrekken van voedingsstoffen."]}),"\n",(0,t.jsx)(n.h2,{id:"voor-60-miljoen-amerikanen-zijn-de-belastingen-zo-eenvoudig-dat-de-belastingdienst-ze-automatisch-kan-doen",children:"Voor 60 miljoen Amerikanen zijn de belastingen zo eenvoudig dat de belastingdienst ze automatisch kan doen."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns",children:"Origineel"}),'.\nTen minste 41% van de Amerikaanse huishoudens, of 62 miljoen belastingaangifte-eenheden, zouden hun volledige belastingaangifte door de IRS kunnen laten afhandelen via "vooraf ingevulde aangiften" zonder dat verdere tussenkomst nodig is. De minder conservatieve benadering schat het aantal op 73 miljoen aangiften, of 48%. Het potentieel voor automatische aangiften zou elk jaar tijd en angst kunnen besparen en het belastingseizoen effici\xebnter maken. Het artikel gaat verder kort in op andere onderwerpen die niets met belastingen te maken hebben, zoals de crisis rond seksueel misbruik van kinderen door de katholieke kerk en het feit dat de camera\'s van Tesla onder vuur liggen. Het belicht echter vooral unieke oplossingen voor belangrijke problemen, die in de nieuwsbrief Future Perfect aan bod komen. Het artikel blijft neutraal en informatief, zonder enige politieke of religieuze vooringenomenheid.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476709",children:"Discussion Service"}),".\nBelasting van 60M Amerikanen eenvoudig genoeg voor IRS om automatisch te berekenen. Makkelijkste manier voor IRS om geld te verdienen is het controleren van financieel kwetsbare mensen. Intuit draagt bij aan het fenomeen van ondoorzichtige wetten. Handhaving IRS is beperkt, dus Amerikanen met een laag inkomen worden meer gecontroleerd. Recente belastingwijzigingen betekenen minder ruimte voor aftrekposten. De IRS kan zijn automatische belastingcapaciteit niet maximaliseren. IRS-budget verlaagd, onlangs verhoogd; sommigen geloven dat de extra financiering de IRS in staat zal stellen de inkomsten te maximaliseren in plaats van zich te richten op specifieke mensen. Voorstel om belasting te heffen op basis van X tarief, aangifte indien niet akkoord. Vooraf ingevulde aangiften zouden tijd en geld besparen, maar zijn niet waterdicht. Bedrijfslobby's dragen bij tot de complexiteit van het huidige zelfbedieningssysteem. Aftrek van omzetbelasting voor contante transacties is niet haalbaar voor automatisering. Belastingvoorbereiding verspilt miljarden dollars en tijd."]}),"\n",(0,t.jsx)(n.h2,{id:"we-moeten-de-mensen-vertellen-dat-chatgpt-tegen-hen-zal-liegen-niet-debatteren-over-taalkunde",children:"We moeten de mensen vertellen dat ChatGPT tegen hen zal liegen, niet debatteren over taalkunde"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/",children:"Origineel"}),".\nHet artikel bespreekt de problemen rond grote taalmodellen (LLM's) zoals ChatGPT, die tegen mensen kunnen liegen en bugs hebben die zich niet laten repareren. De auteur betoogt dat het belangrijker is mensen te waarschuwen voor de risico's van het gebruik van LLM's dan te debatteren over taalkunde. Hoewel LLM's nuttig kunnen zijn, zijn ze niet gevoelig en kan niet worden vertrouwd op het verstrekken van feitelijke informatie. Het artikel werpt ethische vragen op over de vraag of we mensen al dan niet moeten aanmoedigen om LLM's te gebruiken ondanks hun gebreken. De auteur concludeert dat het belangrijk is LLM's met voorzichtigheid te benaderen en benadrukt de noodzaak mensen te waarschuwen dat ChatGPT kunnen liegen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35483823",children:"Discussion Service"}),".\nChatGPT kan gebruikers misleiden en er moet herhaaldelijk op worden gewezen dat het niet te vertrouwen is. Het nut ervan kan beperkt zijn als de neiging tot hallucineren niet wordt opgelost. ChatGPT heeft geen redeneervermogen en kan valse informatie genereren. Sommigen zijn enthousiast over de potenti\xeble vooruitgang, maar sommigen bekritiseren het omdat het niet kan abstraheren of redeneren. AI-gegenereerde tekst vereist scepsis en moet worden gezien als een assistent die goed kan lezen, maar mogelijk vatbaar is voor verwarring. ChatGPT is echter nuttig bij het genereren van codevoorbeelden en het beantwoorden van complexe vragen. Het biedt tot 99% van de tijd nauwkeurige antwoorden. Gebruikers moeten zijn beperkingen begrijpen om te voorkomen dat ze meer moraal toekennen aan ChatGPT dan nodig is."]}),"\n",(0,t.jsx)(n.h2,{id:"twitter-staat-het-retweeten-van-tweets-met-een-link-naar-substack-niet-toe",children:"Twitter staat het retweeten van tweets met een link naar Substack niet toe."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/",children:"Origineel"}),".\nTwitter is begonnen met het beperken van tweets met links naar Substack.com als reactie op Substacks aankondiging van een nieuw product, Notes, dat rechtstreeks met Twitter zal concurreren. Gebruikers hebben gemerkt dat ze tweets met Substack-links niet kunnen retweeten of beantwoorden, en Twitter is blijkbaar begonnen met het blokkeren van tweet-embedding in Substack-berichten. Deze beperking is waarschijnlijk een poging van Twitter om het bereik van een concurrent op zijn platform te beperken. Twitter begon in december 2022 op vergelijkbare wijze links naar concurrerende social media platforms te blokkeren. Substack heeft nog niet gereageerd op vragen hierover."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35482222",children:"Discussion Service"}),".\nTwitter verbood retweets van tweets die linken naar Substack, waarbij het liken van dergelijke berichten de discussie onderdrukt. De zet heeft geleid tot kritiek op de vrije meningsuiting, Elon Musks standpunt daarover en de concurrentie van Substack. Mastodon wordt gezien als vervanging van Twitter voor sommigen. Discussies over PR, sociale media verslaving en twijfelachtige praktijken komen aan bod. Er wordt geen nieuwe technologie of release genoemd."]}),"\n",(0,t.jsx)(n.h2,{id:"western-digital-clouddiensten-4-dagen-uit-de-lucht",children:"Western Digital clouddiensten 4 dagen uit de lucht."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://status.mycloud.com/os4",children:"Origineel"}),".\nWestern Digital ondervond een storing die op 2 april begon en invloed had op diensten als My Cloud, My Cloud Home, SanDisk ibi en andere gerelateerde producten. Op 3 april werd een update gepubliceerd. De storing duurde tot 7 april en had invloed op de toegang tot bestanden en applicaties. Lokale toegang is beschikbaar, zodat gebruikers hun persoonlijke bestanden vanaf een Windows- of MacOS-computer kunnen openen. Andere incidenten uit het verleden zijn intermitterende toegangsproblemen, intermitterende wachtwoordresets en intermitterende verbindingsproblemen met clouddiensten. Bepaalde gebruikers in China kunnen ook toegangsproblemen ondervinden."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35478007",children:"Discussion Service"}),".\nDe clouddiensten van Western Digital liggen al vier dagen plat, met commentaren over de storing en de garantie van het bedrijf. Sommige gebruikers bespreken de beperkingen van het taalmodel en het wereldmodel van GPT, met vragen over het begrip van complexe concepten. Reacties gaan ook over juridische termen rond GPT's service verantwoordelijkheid en garanties. Gebruikers discussi\xebren over de waarde van statuspagina's tijdens uitval, waarbij sommigen alternatieve methoden zoals chat voorstellen. Gebruikers bespreken de voor- en nadelen van self-hosting, met een gewenste toekomst waarin de media van mensen overal toegankelijk zijn. De problemen die Western Digital in het verleden heeft gehad met SMR-schijven die niet naar behoren werden gemarkeerd, hebben sommige gebruikers ertoe aangezet terug te keren naar lokale oplossingen."]}),"\n",(0,t.jsx)(n.h2,{id:"hoe-werkt-database-sharding",children:"Hoe werkt database sharding?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://planetscale.com/blog/how-does-database-sharding-work",children:"Origineel"}),'.\nHet artikel gaat in op database sharding, waarbij de voordelen van schaling-out in plaats van schaling-up met verschillende sharding-schema\'s en algoritmen worden besproken. Het behandelt vitale aspecten zoals het organiseren van infrastructuur, het cre\xebren van routinglagen en migratieplanning, waarbij het belang van onderhoud wordt benadrukt. Er wordt een kort overzicht gegeven van sharding frameworks en tools zoals Vitess en Citus, waarbij CockroachDB het tijdperk van "serverloze" databases inluidt. PlanetScale, een opkomende speler op de markt, biedt een shard-native database die is gebouwd op MySQL en Vitess, naast haar technische middelen.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476518",children:"Discussion Service"}),".\nDebatten over voordelen & uitdagingen van database sharding; kies voor systeem dat overeenkomt met data; hot key throughput een probleem bij auto-sharding; Spanner/Cockroach of Dynamo/Cassandra alternatieven; CockroachDB biedt sterke consistentie en 2PC tussen shards; distributie complexiteiten vereisen betaalde diensten; focus op horizontale schaalbaarheid om investering in single machine te vermijden; goed sleutelontwerp kan hotspots voorkomen; sharding per klant is gebruikelijk; multi-tenant sharding voorgesteld voor schaalbaarheid; Yugabyte, Cockroach, & TiDB genoemd; hashing van alle data voor synchronisatie niet schaalbaar; scammers maken gebruik van Amazon's table colocation praktijk; MongoDB vereist enterprise support contract."]}),"\n",(0,t.jsx)(n.h2,{id:"hubble-ziet-mogelijk-op-hol-geslagen-zwart-gat-dat-een-spoor-van-sterren-cre\xebert",children:"Hubble ziet mogelijk op hol geslagen zwart gat dat een spoor van sterren cre\xebert"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://hubblesite.org/contents/news-releases/2023/news-2023-010",children:"Origineel"}),".\nKan geen samenvatting genereren omdat de tekst een foutmelding is die aangeeft dat aan het verzoek niet kon worden voldaan wegens een configuratiefout of te veel verkeer. Contact opnemen met de eigenaar van de app of website of de CloudFront-documentatie doornemen kan helpen bij het oplossen van problemen en het voorkomen van deze fout."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476359",children:"Discussion Service"}),'.\nDe Hubble-telescoop zag een zwart gat dat een spoor van sterren achterliet, wat leidde tot speculaties over het effect ervan op leven, en nieuwe plaatsen om bewoonbare planeten te vinden. Hubble vond ook een zeldzaam Hoag-type sterrenstelsel, ongeveer twee keer zo groot als de Melkweg. Wetenschappers ontdekten een zwart gat dat uit gas sterren cre\xebert, wat het heelal kan be\xefnvloeden en geavanceerde beschavingen kan aantrekken. Een object dat zeer snel door de ruimte reist, cre\xebert een supersonische impact op gas, maar het gebruik van "supersonisch" is waarschijnlijk metaforisch. Discussion Service-gebruikers bespreken scifiverhalen zoals The Three-Body Problem, met uiteenlopende meningen en aanbevelingen voor andere boeken in het genre. Gebruikers discussi\xebren ook over de zeldzaamheid van aards leven en het Antropomorf Principe.']}),"\n",(0,t.jsx)(n.h2,{id:"nzs-grootste-datalek-laat-zien-dat-retentie-de-slapende-reus-van-gegevensbeveiliging-is",children:"NZ's grootste datalek laat zien dat retentie de slapende reus van gegevensbeveiliging is"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/",children:"Origineel"}),".\nMeer dan een miljoen Nieuw-Zeelandse rijbewijzen en paspoorten werden blootgelegd bij het datalek bij Latitude Financial; sommige gegevens waren tot 18 jaar oud. De Deputy Privacy Commissioner van Nieuw-Zeeland noemt het bewaren van gegevens als een kritiek punt bij cyberbeveiligingsaanvallen en stelt dat bedrijven en organisaties het verzamelen en bewaren van gegevens die zij niet nodig hebben, moeten beperken. Instanties moeten een schema opstellen voor het bewaren van persoonsgegevens, en particulieren moeten organisaties waaraan zij informatie verstrekken, vragen waarom en hoe deze wordt bewaard. Privacy moet een cruciale bedrijfskwestie worden, met dezelfde bescherming als gezondheid en veiligheid. Latitude Financial neemt contact op met alle getroffen klanten om hen op de hoogte te stellen van de inbreuk en te helpen bij het oplossen ervan."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35478240",children:"Discussion Service"}),".\nNZ's grootste datalek onderstreept noodzaak van goed beleid voor gegevensbewaring; verwijdering moet prioriteit krijgen. GDPR heeft vooruitgang geboekt, maar dataretentie blijft alomtegenwoordig. Discussion Service-gebruikers bespreken verantwoorde gegevensverzameling, toegang van de overheid en gegevensbeveiliging. De methoden en redenen voor het wissen van gegevens worden besproken. Persoonsgegevens moeten worden geminimaliseerd en behandeld als giftige activa. Bedrijven moeten beter worden voorgelicht over dataprivacy."]}),"\n",(0,t.jsx)(n.h2,{id:"vs-en-china-voeren-oorlog-onder-de-golven-over-internetkabels",children:"VS en China voeren oorlog onder de golven over internetkabels"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/",children:"Origineel"}),".\nDe VS en China vechten om onderzeese kabels die alles van e-mails tot militaire geheimen doorgeven. De Amerikaanse regering heeft de afgelopen vier jaar ingegrepen in minstens zes particuliere onderzeese kabeltransacties om de Chinese hightechsector te isoleren en de Chinese toegang tot Amerikaanse technologie te beperken. Het Witte Huis heeft onlangs om veiligheidsredenen het kabelcontract tussen Singapore en Frankrijk gegund aan het Amerikaanse SubCom en niet aan het Chinese HMN Tech. De agressieve inspanningen van de Amerikaanse regering om Chinese spionage via onderzeese kabels te voorkomen, verstoren de plannen van technologiereuzen en veroorzaken onrust in de sector. China neemt wraak door een door Meta gesteund kabelproject, de Zuidoost-Azi\xeb-Japan 2 kabel, te vertragen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481712",children:"Discussion Service"}),'.\nDe VS en China wedijveren over onderzeese internetkabels, met zorgen over nationale grenzen en censuur. Vertragingen en omleidingen van kabels hebben techgiganten miljoenen gekost. Deskundigen bevelen boeken aan over internationale infrastructuur. De VS zijn bezorgd over Chinese spionage en hun vermogen om internetverkeer te verzamelen en te filteren. China\'s betrokkenheid bij de niet-gebonden beweging en het "Belt and Road"-initiatief roept vragen op. Veel "cyberbeveiligingsbedrijven" hebben een gebrek aan geschoolde ingenieurs. Het martelprogramma van de CIA en de aansprakelijkheid voor oorlogsmisdaden worden besproken.']}),"\n",(0,t.jsx)(n.h2,{id:"database-sharding-kwam-van-ultima-online",children:'Database "sharding" kwam van Ultima Online?'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.raphkoster.com/2009/01/08/database-sharding-came-from-uo/",children:"Origineel"}),".\nSorry, ik kan geen samenvatting maken op basis van deze tekst omdat het een foutmelding is en geen verband houdt met het opgegeven onderwerp."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35479553",children:"Discussion Service"}),'.\nDiscussion Service-gebruikers bespreken hoe "sharding" in databases werd ge\xefnspireerd door Ultima Online. Persoonlijke verhalen vertellen hoe UO leidde tot het leren coderen. Posters halen herinneringen op aan de spelkenmerken van UO en de invloed ervan op het programmeren.']}),"\n",(0,t.jsx)(n.h2,{id:"waarom-deelde-phreesia-mijn-medische-gegevens-nadat-ik-me-had-afgemeld",children:"Waarom deelde Phreesia mijn medische gegevens nadat ik me had afgemeld?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/",children:"Origineel"}),".\nEen rapport belicht medische bedrijven die pati\xebntgegevens delen zonder toestemming. Pati\xebnte weigerde het delen van gegevens, maar ontdekte toch dat haar gegevens door Phreesia werden gedeeld. Suggestie voor een regel tegen het onder druk zetten van de pati\xebnt voor toestemming. Noodzaak van een standaard opt-out om opt-out duidelijk en gemakkelijk te maken. Het huidige proces is omslachtig. Expert stelt voor om ad tech te scheiden van gezondheidszorg. Auteur is etnografisch socioloog en gegevensonderzoeker."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35484978",children:"Discussion Service"}),".\nPhreesia deelde medische gegevens van pati\xebnten die zich afmeldden. Velen maken zich zorgen over de privacy van de gegevens en de verantwoordingsplicht, en suggereren dat reclame met gevoelige medische gegevens wettelijk niet zou mogen. Er moet goed worden gedocumenteerd en gerapporteerd om dergelijke bedrijven aansprakelijk te stellen voor schendingen van de privacy. Het gebruik van elektronische check-ins en dark patterns door zorgverleners is bekritiseerd. In de VS zijn strenge toestemmingswetten en handhaving inzake gegevensverzameling nodig. Het winstoogmerk van zorgverleners en de wrok tegen de privacyregels voor pati\xebnten komen ook ter sprake."]}),"\n",(0,t.jsx)(n.h2,{id:"javascript-algoritmen-algoritmen-en-gegevensstructuren-ge\xefmplementeerd-in-javascript",children:"JavaScript-algoritmen: Algoritmen en gegevensstructuren ge\xefmplementeerd in JavaScript"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/trekhleb/javascript-algorithms",children:"Origineel"}),".\nJavaScript-Algoritmen is een uitgebreide verzameling van populaire algoritmen en gegevensstructuren ge\xefmplementeerd in JavaScript, georganiseerd per onderwerp en paradigma. Het is geschikt voor leer- en onderzoeksdoeleinden en productiegebruik. Gebruikers kunnen voorbeelden vinden van verschillende populaire algoritmen en gegevensstructuren, waaronder encryptie-, evolutie- en machineleeralgoritmen. Het archief bevat uitleg, Big O-notatie en links naar verdere lectuur. Het bevat ook een speelplaats voor lezers om te experimenteren met de code. Geavanceerde algoritmen zoals branch and bound en dynamisch programmeren zijn inbegrepen. Lezers moeten weten dat donaties welkom zijn en dat Node versie 16 of hoger vereist is."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35479378",children:"Discussion Service"}),".\n\"Hacker News geeft commentaar op populaire GitHub repository 'JavaScript-algorithms'. Gebruikers bespreken de geschiktheid van de taal voor onderwijs en praktisch gebruik, sommigen waarschuwen voor onverwacht gedrag. Sommige Discussion Service-gebruikers bekritiseren de implementatie van de methoden 'addBefore()' en 'addAfter()' van gekoppelde lijsten, terwijl anderen het daar niet mee eens zijn. Discussion Service-gebruikers bevelen verdere bronnen aan, bekritiseren de effici\xebntie van datastructuren en benadrukken de waarde van bronnen voor het leren van algoritmen.\""]}),"\n",(0,t.jsx)(n.h2,{id:"spacex-nadert-eerste-starship-super-heavy-lancering",children:"SpaceX nadert eerste Starship Super Heavy lancering"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/",children:"Original"}),".\nSpaceX plant de eerste lancering van het volledige Starship-voertuig later in april, in afwachting van de goedkeuring van de regelgeving; de Federal Aviation Administration heeft in haar adviesdocument over het operatieplan een lanceerdatum van 17 april genoteerd, met reservedata van 18 tot 21 april; Starship is volledig gestapeld op het platform in zijn Starbase faciliteit in Boca Chica, Texas, en het bedrijf plant een lanceringsrepetitie volgende week, gevolgd door de eerste ge\xefntegreerde vliegtest ongeveer een week later; Het is onduidelijk of Starship in een baan om de aarde zal komen en dan onmiddellijk een deorbitbranding zal uitvoeren om naar beneden te spatten, of dat het een lange suborbitale vlucht is."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481775",children:"Discussion Service"}),".\nSpaceX nadert lancering van Starship Super Heavy, met commentaar dat het belang ervan benadrukt voor commerci\xeble en militaire ruimtevaart en een mentaliteitsverandering. Overheidscontracten vormen minstens 80% van SpaceX' inkomsten. Starship's cryogene raketten met vloeibare brandstof zijn haalbaar voor afschrikkingsmissies. De financiering van lanceringen is niet alleen afhankelijk van NASA. Video met vergelijking van raketgroottes krijgt aandacht. SpaceX mikt voorlopig op lancering op 20 april. FAA overweegt veiligheidsproblemen. Gemengde reacties op Musk's oneerbiedige houding."]}),"\n",(0,t.jsx)(n.h2,{id:"muzikale-synthesizers-bouwen-met-sql-queries",children:"muzikale synthesizers bouwen met SQL queries."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/ClickHouse/NoiSQL",children:"Origineel"}),".\nEen GitHub repository genaamd NoiSQL maakt het mogelijk muzikale geluiden te genereren met SQL-queries, met behulp van basisgolven, oscillatoren, sequencers, LFO's en ruisgeneratoren. Gemaakt in een 44,1kHz 16-bit stereo PCM formaat, kunnen gebruikers signalen aansturen door functies en expressies in SQL te defini\xebren. NoiSQL biedt instructies en voorbeelden om het te leren gebruiken. Het project kan muzieknoten en ritmes genereren met ClickHouse en kan verschillende bestandsformaten aanmaken. Hoewel het project heeft een aantal beperkingen, het is een innovatieve manier om te experimenteren met ClickHouse de functies, en het kan mogelijk uit te breiden naar video generatie op te nemen. Gebruikers kunnen nieuwe voorbeelden bijdragen aan het project."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35482636",children:"Discussion Service"}),".\nEen project dat synthesizers bouwt met SQL-queries. Discussion Service-commentatoren waarderen het unieke idee en vermelden soortgelijke projecten. Sommige gebruikers wijzen op het gebrek aan uitleg en de mogelijke kwetsbaarheid voor SQL-injectie."]}),"\n",(0,t.jsx)(n.h2,{id:"de-langste-rechte-lijn-in-groot-brittanni\xeb-zonder-een-openbare-weg-te-kruisen",children:"De langste rechte lijn in Groot-Brittanni\xeb zonder een openbare weg te kruisen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://www.statsmapsnpix.com/2023/04/the-longest-straight-line-in-great.html",children:"Origineel"}),".\nIn Groot-Brittanni\xeb is een langere rechte lijn gevonden zonder een openbare weg te kruisen dan de lijn die in 2019 door Ordnance Survey is vastgesteld. De langste rechte lijn tussen wegen in Groot-Brittanni\xeb is ook de langste in het hele Verenigd Koninkrijk. Het OS Open Roads product biedt veel geweldige open data, maar soms bevat het wegen die niet openbaar zijn. Beperkte lokale toegangswegen zijn meestal onverharde priv\xe9wegen. De langste lijn in Groot-Brittanni\xeb ligt ten westen van de A9 in plaats van ten oosten. Hoewel kaartgegevens nuttig zijn, moeten ze met een korreltje zout worden genomen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481380",children:"Discussion Service"}),".\nDe langste rechte lijn in Groot-Brittanni\xeb ontdekt; mogelijk niet perfect recht. Enige discussie over afstand tot wegen, toegankelijkheid van onverharde wegen en bevolking. Gebruikers noemen afgelegen gebieden in de wereld en de mogelijkheid om het zoeken te automatiseren. Een discussie over Schengen-overeenkomst en paspoortstatistieken."]}),"\n",(0,t.jsx)(n.h2,{id:"flipper-zero-verboden-door-amazon-omdat-het-een-card-skimming-device-is",children:'Flipper Zero verboden door Amazon omdat het een "card skimming device" is'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/",children:"Origineel"}),'.\nAmazon heeft de verkoop van Flipper Zero op zijn platform verboden omdat het een "card skimming device" zou zijn. Het apparaat is een compacte, draagbare en programmeerbare tool die kan helpen bij het experimenteren met en debuggen van verschillende digitale en hardware apparaten. Gebruikers hebben de mogelijkheden ervan laten zien, wat Amazon\'s verbod stimuleerde. Sommige links naar voorheen beschikbare Amazon pagina\'s die de Flipper Zero tool verkopen zijn dood, terwijl andere het als "niet beschikbaar" vermelden. Het Braziliaanse Nationale Telecommunicatie Agentschap heeft ook inkomende Flipper Zero aankopen in beslag genomen op basis van het vermeende gebruik door criminelen. U kunt Flipper Zero nog steeds kopen in de offici\xeble winkel van de maker.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481580",children:"Discussion Service"}),".\nAmazon verbiedt aankoop van Flipper Zero omdat het wordt beschouwd als een card skimming apparaat, maar apparaat kan worden gekocht in de offici\xeble winkel. Kopers vinden het interessant maar niet nuttig. Lockpick verbodsbeleid is inconsistent en niet gedocumenteerd. Makers van Flipper Zero gebruiken een Amerikaans bedrijf voor betalingen, wat zorgen over de veiligheid oproept. De motivatie van Amazon werd in twijfel getrokken om krantenkoppen te vermijden die hen associ\xebren met misdaad. Flipper Zero is verboden vanwege het potentieel voor illegale activiteiten, maar volgens sommigen is het beleid van Amazon inconsistent. Sommigen zien mogelijkheden voor Amazon om zijn eigen namaakversie te ontwikkelen. Flipper Zero verwijderd van Amazon en eBay, maar kan nog steeds gekocht worden via de offici\xeble site."]}),"\n",(0,t.jsx)(n.h2,{id:"omgekeerde-engineering-van-de-facebook-messenger-api",children:"Omgekeerde engineering van de Facebook Messenger API"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://intuitiveexplanations.com/tech/messenger",children:"Origineel"}),".\nDe auteur heeft de Facebook Messenger API reverse-engineered om Messyger te maken, een commandoregelprogramma. Het bericht legt het inlogproces en cookies uit en biedt Python-code op GitHub. Ethisch gedrag wordt benadrukt, en er worden tips gegeven voor het doen van verzoeken buiten de browser om."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35477160",children:"Discussion Service"}),".\nOntwikkelaars claimen opgeblazen & ineffici\xebnte Messenger API. Facebook apps bibliotheek heeft JNI bindingen. Behoefte aan third-party clients, Digital Markets Act aangehaald. Spam & data harvesting zorgen, reverse engineering tools gedeeld. Winstbejag leidt tot minder spam, sommigen steunen overheidsingrijpen. Regelgeving moet zich richten op cloud providers, niet op walled gardens. Gebruiker zet vraagtekens bij het begrip eigendom en reddingsoperaties voor bedrijven."]}),"\n",(0,t.jsx)(n.h2,{id:"de-machines-van-tatjana-van-vark",children:"De machines van Tatjana van Vark"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/",children:"Origineel"}),".\nTatjana van Vark, een onafhankelijk onderzoeker uit Nederland, heeft een grote verscheidenheid aan wetenschappelijke instrumenten gebouwd, nagemaakt en gerestaureerd. Haar uitgebreide projecten getuigen van uitstekend vakmanschap en aandacht voor detail, vaak met complexiteiten die verder gaan dan het uiterlijk. Tatjana's werk bracht haar in vele gebieden van wetenschappelijke studie, het bouwen van stukken in de elektronica, optica, cryptologie, organische chemie, en nog veel meer. Ondanks haar autodidactische machinale vaardigheden, bevat haar werkplaats hoogwaardige machines die de eisen van haar precisiewerk aankunnen. Haar werk is wetenschappelijk vakmanschap op het hoogste niveau, met indrukwekkende foto-exposities op haar website."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35483539",children:"Discussion Service"}),".\nHet werk van Tatjana van Vark is ongelooflijk, en ze is een extreme hacker, die instrumenten vanaf nul bouwt. Ze heeft een breed scala aan vaardigheden en heeft veel werken geproduceerd die een leven lang zouden duren om te beoordelen. Er is bezorgdheid over een krimpend aantal deskundigen nu de technologie zich sneller ontwikkelt dan wij haar kunnen onderwijzen. Tatjana van Vark en ambachtslieden zoals zij zijn nog nooit zo gewoon geweest."]}),"\n",(0,t.jsx)(n.h2,{id:"grote-bal-modder-1999",children:"Grote bal modder (1999)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://www.laputan.org/mud/",children:"Origineel"}),".\nHet artikel onderzoekt de BIG BALL OF MUD software architectuur en waarom deze blijft bestaan ondanks hoogstaande benaderingen. Zeven patronen worden besproken, waaronder wegwerpcode en fragmentarische groei, en de achterliggende oorzaken, zoals tijdsdruk en verwaarlozing van de architectuur. Voorbarige architectuur kan evolutie in de weg staan, en onervarenheid of personeelsverloop kan verfijning beperken. Pair programming en code reviews worden aanbevolen voor onmiddellijk onderzoek, terwijl refactoring, reparatie en consolidatie cruciaal zijn voor het bestrijden van BIG BALL OF MUD. Het benadrukt het belang van incrementele groei, onderhoud, aanpassing en rigoureus testen. Een systeem herbouwen kan nodig zijn, maar refactoring kan een alternatief bieden door architecturale elementen uit het huidige systeem te halen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481309",children:"Discussion Service"}),'.\nHet artikel "Big Ball of Mud (1999)" is een gewaardeerd stuk over software engineering. Verschillende gebruikers roemen het inzicht en de relevantie ervan en noemen het een uitgebreide verklaring voor wat men elke week in re\xeble situaties ziet. Anderen wijzen op andere soortgelijke artikelen of latere ontwikkelingen in software engineering, zoals microservices. Sommige gebruikers geven commentaar op hun persoonlijke ervaringen met betrekking tot het artikel. Ten slotte geven sommige gebruikers kritiek op de opmaak van het artikel of merken op dat het eerder is geplaatst.']}),"\n",(0,t.jsx)(n.h2,{id:"yann-lecun-en-andrew-ng-waarom-de-ai-pauze-van-6-maanden-een-slecht-idee-is-video",children:"Yann LeCun en Andrew Ng: Waarom de AI-pauze van 6 maanden een slecht idee is [video]."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.youtube.com/watch?v=BY9KV8uCtj4",children:"Origineel"}),".\nDit is niet de eigenlijke inhoud van het artikel. Geef me de tekst om samen te vatten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35484093",children:"Discussion Service"}),".\nYann LeCun en Andrew Ng bekritiseren de 6-maanden AI-pauze, suggererend dat het onrealistisch is en een voordeel geeft aan OpenAI. Debatten over AI-winter, menselijke gedachtevoorstelling en maatschappelijke ontwrichting worden belicht. De vooruitgang van AI biedt onverwachte mogelijkheden die verder gaan dan tekst en er is bezorgdheid over banenverlies en armoede. Deskundigen hebben gemengde meningen over de effectiviteit van de pauze op AI-ontwikkeling en de risico's van ongereguleerde AI. De potenti\xeble dreiging van AGI die de menselijke intelligentie overtreft en deep learning surveillance technologie\xebn worden aan de orde gesteld, naast zorgen over de afstemming van AI op menselijke doelen."]}),"\n",(0,t.jsx)(n.h2,{id:"nsa-cre\xeberde-online-cursus-cyberbeveiliging-met-100-lessen",children:"NSA cre\xeberde online cursus cyberbeveiliging met 100 lessen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://clark.center/c/nccp",children:"Origineel"}),".\nDe NSA heeft een online cursus cyberbeveiliging opgezet met honderden beschikbare lessen. De cursus, genaamd CLARK, behandelt een groot aantal onderwerpen, waaronder netwerkbeveiliging, cryptografie en cyberdreigingen. De lessen zijn bedoeld voor zowel beginners als deskundigen, en zijn gratis toegankelijk voor iedereen met een internetverbinding. Er is enige controverse geweest rond de cursus, waarbij sommige critici beweerden dat de cursus een achterdeur biedt voor de NSA om toegang te krijgen tot priv\xe9gegevens. De NSA heeft deze beweringen echter ontkend en stelt dat de cursus zuiver educatief is."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481456",children:"Discussion Service"}),".\nDe NSA heeft een cursus cyberbeveiliging opgezet, maar er bestaat bezorgdheid over het gebruik van 0day-exploits door het agentschap bij offensieve operaties. Sommige gebruikers merken op dat de splitsing tussen aanval en verdediging minder onheilspellend is dan het lijkt. De cursus maakt deel uit van het CLARK System, dat gedeeltelijk wordt gefinancierd door de NSA, maar voornamelijk wordt geleid door de Towson University. Sommige gebruikers bekritiseren het gebrek aan aandacht voor bepaalde onderwerpen in de cursus."]}),"\n",(0,t.jsx)(n.h2,{id:"slechte-systemen-vervangen-door-slechte-systemen",children:"Slechte systemen vervangen door slechte systemen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://seths.blog/2023/04/replacing-bad-systems-with-bad-systems/",children:"Origineel"}),".\nIn zijn blogpost gebruikt Seth de metafoor van verouderde parkeermeters om de noodzaak te illustreren om slechte systemen te heroverwegen en te verbeteren. Hoewel vervanging duur lijkt, hebben gecentraliseerde systemen zoals de Parkmobile app vaak hun eigen tekortkomingen. Terugkomend op het oorspronkelijke doel om inkomsten te genereren en de hele dag parkeren te voorkomen, stelt Seth voor om een gratis app te implementeren die een code scant om een parkeerperiode toe te staan. Andere inkomstenverhogende opties zijn een online betaaldienst of de verkoop van parkeerpassen met verschillende kortingsopties. Hoewel het moeilijk is om UX-keuzes te maken voor een openbaar systeem, hebben gedistribueerde systemen zoals WordPress het goed gedaan vanwege hun gedecentraliseerde en gebruiksvriendelijke ontwerp. Het belangrijkste voordeel van gedistribueerde systemen is dat ze in de loop van de tijd kunnen verbeteren, in plaats van verkalken zoals bij gecentraliseerde systemen. Om vooruit te komen, stelt Seth voor dat we voorrang geven aan betere oplossingen in plaats van meer oplossingen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476350",children:"Discussion Service"}),".\nEen eenvoudiger parkeersysteem in Denemarken heeft handmatige klokken, met boetes voor valsspelers. Gebruikers wijzen op vergelijkbare systemen in het buitenland. Vaak worden complexe oplossingen gebruikt ondanks eenvoudige opties. Parkeermeters in Chicago leverden in 10 jaar 200 miljoen dollar op. Nieuwe elektronische parkeermeters zijn minder handig dan de klassieke. Overheden worstelen met betalingssystemen en laten het soms over aan verkopers. Parkeermeters worden vooral gebruikt voor geld, maar ze verhinderen ook de hele dag parkeren. Het artikel had geen punt volgens een commentator, terwijl een andere de auteur bekritiseert."]}),"\n",(0,t.jsx)(n.h2,{id:"neovim-09",children:"Neovim 0.9"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/neovim/neovim/commit/040f1459849ab05b04f6bb1e77b3def16b4c2f2b",children:"Origineel"}),".\nNeovim versie 0.9.0 is uitgebracht, met wijzigingen aan iconv, libintl, optionele params, lua2dox, semantische tokens, '+tui', ondersteuning voor Yarn node modules, en code block highlighting. Vim versie 8.2.2902 is ook uitgebracht met bugfixes en verbeterde ondersteuning voor Lua scripting en LSP. De nieuwste release van Neovim bevat spannende nieuwe functies en stabiliteitsverbeteringen, terwijl Vim zich richt op bugfixes en verbeterde functionaliteit. De updates van Neovim omvatten verbeteringen aan 'treesitter,' 'tui,' en 'windows,' van software fixes tot verbeterde documentatie, die de Neovim ervaring stroomlijnen en zijn positie als capabel en gebruiksvriendelijk verstevigen. Andere updates zijn wijzigingen in de 'expect_unchanged()' functie, EditorConfig en syntax highlighting voor helpbestanden, een headless instance, verbeterde LSP client mogelijkheden, en plugin ondersteuning voor GUI's."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35480629",children:"Discussion Service"}),".\nNeovim 0.9.0 undeprecates 'exrc' en voegt een \"trust database\" toe. Experts raden appImage of .local aan voor installatie. EditorConfig ondersteuning is nu ingebouwd. Debat over de verdiensten van Neovim, terwijl sommigen de fragmentatie bekritiseren, stellen anderen plugin managers voor. Neovim maakt nieuwe gereedschappen en plugins mogelijk. Lua heeft voordelen voor plugin-ontwikkeling. Helix Editor heeft een object-verb model, zero config language server en een tutor. Het aanbod is minder flexibel, maar gebruikers zijn enthousiast over de bruikbaarheid en effici\xebntie."]}),"\n",(0,t.jsx)(n.h2,{id:"vraag-wat-is-uw-beste-bron-om-op-de-hoogte-te-blijven-van-ai-ontwikkelingen",children:"Vraag Wat is uw beste bron om op de hoogte te blijven van AI-ontwikkelingen?"}),"\n",(0,t.jsx)(n.p,{children:"N/A (Aangezien dit slechts algemene instructies zijn voor het samenvatten, is er geen tekst om samen te vatten)."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35479853",children:"Discussion Service"}),".\nDiscussion Service-gebruikers bevelen bronnen aan om op de hoogte te blijven van AI-ontwikkelingen, zoals de Papers with Code-website, blogs en nieuwsbrieven. Voorzichtigheid is geboden vanwege de overvloed aan informatie. Sommige bieden hulpmiddelen voor beginners. Recente vooruitgang in AI, met inbegrip van hardware en algoritmische innovaties, heeft de training van grote neurale netwerken verbeterd en prestaties op menselijk niveau bereikt. Het debat over revolutionaire doorbraken gaat door."]}),"\n",(0,t.jsx)(n.h2,{id:"direct-bewijs-van-het-gebruik-van-meerdere-drugs-in-de-bronstijd-uit-een-menselijke-haartest",children:"Direct bewijs van het gebruik van meerdere drugs in de Bronstijd uit een menselijke haartest."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.nature.com/articles/s41598-023-31064-2",children:"Original"}),".\nEen studie vond direct bewijs van meerdere psychoactieve plantensoorten in Menorca in de Bronstijd door analyse van menselijk haar. De haren bevatten efedrine, atropine en scopolamine. Archeologen leiden het gebruik van geestverruimende middelen gewoonlijk af uit artefacten, maar deze analyse is rechtstreeks. Deze ontdekking werpt een nieuw licht op het drugsgebruik in oude samenlevingen en wijst op gespecialiseerde kennis en mogelijk sjamanistisch gebruik. De studie laat zien hoe belangrijk het is om de rol van psychoactieve planten en drugsgebruik in culturen uit het verleden te begrijpen. Meerdere studies tonen bewijs voor het gebruik van psychoactieve planten in oude culturen en benadrukken de lange geschiedenis van menselijk drugsgebruik."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35486923",children:"Discussion Service"}),".\nHaartesten tonen drugs aan in Bronstijd met meerdere psychoactieve soorten. Commentaren bespreken maatschappelijke gevolgen van druggebruik, persoonlijke keuze, opvoeding en waarden. Drugsverbod geworteld in volksgezondheid, moraal en racisme. Neutraal artikel vermijdt politieke vooringenomenheid en speculatie."]}),"\n",(0,t.jsx)(n.h2,{id:"nypd-agenten-scheppen-op-over-het-uitmelken-van-overuren-in-toevallige-opname",children:"NYPD agenten scheppen op over het uitmelken van overuren in toevallige opname."}),"\n",(0,t.jsxs)(n.p,{children:["(",(0,t.jsx)(n.a,{href:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording",children:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording"}),').\nEen per ongeluk gemaakte opname tijdens de arrestatie van een bouwvakker heeft politieagenten aan het licht gebracht die opscheppen over het "uitmelken van overuren" en denigrerende taal gebruiken tegenover arrestanten. De opname werpt licht op de manier waarop recente hervormingen van het strafrecht van invloed zijn geweest op de manier waarop agenten arrestaties verwerken en overuren innen. Er wordt gesuggereerd dat politieagenten profiteren van veranderingen in de wetgeving inzake borgtocht en ontdekking om extra overuren te maken. De NYPD heeft geweigerd commentaar te geven op de opname, die ook ongevoelige opmerkingen van agenten over arrestanten bevat.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35487036",children:"Discussion Service"}),".\nNYPD agenten scheppen op over het uitmelken van overuren, maar het artikel onthult hun gebruik van scheldwoorden, grappen over het institutionaliseren van mensen, enz. Volgens sommigen heeft de rechtshandhaving in de VS veel ergere problemen, en zijn de overuren van de politie een afleidingsmanoeuvre. Anderen zeggen dat het uitmelken van overuren door detentie te verlengen ongrondwettelijk is en een aanklacht wegens misdrijf verdient. De corruptie bij de politie heeft geleid tot de roep om afschaffing en vervanging. Een gebrek aan toezicht en controle maakt het uitmelken van overuren en misdrijven mogelijk. Er is bezorgdheid over het gedrag van mensen die wapens en een voorkeursbehandeling krijgen."]}),"\n",(0,t.jsx)(n.h2,{id:"toon-chatgdb---gpt-aangedreven-gdb-assistent",children:"Toon ChatGDB - GPT-aangedreven GDB-assistent"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/pgosar/ChatGDB",children:"Origineel"}),".\nChatGDB is een hulpmiddel dat de debug-ervaring in GDB verbetert door gebruik te maken van de kracht van ChatGPT, waardoor commando's in natuurlijke taal automatisch kunnen worden uitgevoerd. Gebruikers kunnen ChatGPT ook vragen het zojuist uitgevoerde commando uit te leggen of zelfs een vraag te stellen. Om te installeren moeten Python versie 3.3 of hoger en pip worden ge\xefnstalleerd, gevolgd door het commando ",(0,t.jsx)(n.code,{children:"pip3 install chatgdb"})," en het maken van een executable met ",(0,t.jsx)(n.code,{children:"chatgdb -k <API KEY>"}),". De tool kan binnen GDB gebruikt worden door ",(0,t.jsx)(n.code,{children:"chat"})," in te typen gevolgd door het gewenste commando, en het commando ",(0,t.jsx)(n.code,{children:"explain"})," kan gebruikt worden om uitleg te vragen over het vorige commando of om een vraag te stellen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35483933",children:"Discussion Service"}),".\nChatGDB is een door GPT aangedreven GDB-assistent, die debug-workflows verbetert. Discussion Service gebruiker merkt de minimale code van het programma op. ChatGPT versnelt het begrip van de gebruiker voor onbekende technologie, refactoring taken. CLI-versie van ChatGPT voorgesteld. ChatGPT versnelt workflows, ondanks voorkeur van sommige gebruikers voor spiergeheugen. ChatGPT-3 presenteert natuurlijke taal prompt voor GDB, nuttig voor ",(0,t.jsx)(n.code,{children:"geheugenlekken en segmentatiefouten."})," Interface nog steeds onhandelbaar in bepaalde scenario's, maar lettertype en kleurenschema zijn goed ontvangen."]})]})}function v(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);